def sqrt_linear(n: int) -> int:
    i = 1
    while i * i <= n:
        i += 1
    return i - 1

def integer_sqrt(n: int) -> int:
    if n < 2:
        return n
    lo, hi, ans = 1, n // 2, 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if mid * mid <= n:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans
